NIA_DOM_AI = {'IG': ('High', 'Include AI in the information security programme, roles and governance; name owners for AI systems.'),
 'RM': ('High', 'Add AI assets and AI-specific threats to the risk assessment and treatment; use sheet 4 scenarios.'),
 'TM': ('High', 'Apply to AI APIs, cloud AI services and AI features in vendor products; include AI terms in contracts.'),
 'DL': ('High', 'Rate and label AI models, training data, knowledge bases, prompts and outputs (sheets 1 and 5A).'),
 'CM': ('High', 'Treat model retraining, prompt and guard-rail changes and vendor model updates as changes.'),
 'PS': ('Medium', 'Cover AI acceptable use and responsibilities in staff terms and briefings.'),
 'SA': ('High', 'Cover safe AI use, prompt injection, deepfakes and data handling in awareness.'),
 'IM': ('High', 'Include AI incidents (data exposure, agent misuse, deepfake fraud) in incident procedures and reporting.'),
 'BC': ('Medium', 'Plan fallback for AI-dependent services and AI provider outages.'),
 'SM': ('High', 'Log AI prompts, outputs, agent actions and model changes; monitor for abuse.'),
 'DR': ('High', 'Set retention for training data, prompts, outputs and logs; avoid keeping personal data longer than needed.'),
 'DC': ('Medium', 'Document AI systems, models, data and controls.'),
 'AC': ('Medium', 'Include AI systems in audit and certification scope.'),
 'CS': ('Low', 'No AI-specific change; applies to AI infrastructure as to other systems.'),
 'NS': ('Low', 'Applies to AI infrastructure as to other systems; segment AI services and restrict outbound connections.'),
 'IE': ('High', 'Control what data is exchanged with AI services and how outputs are released.'),
 'GS': ('High', 'Filter data exported to and imported from AI services through gateways.'),
 'PR': ('High', 'Apply product selection and evaluation to AI products, models and services.'),
 'SS': ('High', 'Apply secure development and testing to AI applications, including prompt injection and output handling.'),
 'SU': ('High', 'Define acceptable use of AI tools; restrict public AI tools.'),
 'MS': ('Low', 'No AI-specific change; applies to media holding AI data.'),
 'AM': ('High', 'Control access to AI systems, models, data and agent tools; least privilege for agents.'),
 'CY': ('Medium', 'Encrypt models and AI data at rest and in transit; protect keys.'),
 'OS': ('Low', 'Applies to devices used to access AI tools.'),
 'PH': ('Low', 'No AI-specific change.'),
 'VL': ('Low', 'Applies to virtualised AI platforms as to other systems.')}

