NOTES = ['The consequence areas Legal and regulatory compliance, Financial (organisation), Operational (organisation) and Reputation (organisation) in sheet 4 are '
 "additions to the six NISRMF national consequence dimensions; align them with the bank's own impact categories.",
 'Neither QCB nor NCSA publishes a mapping between QCB incident priorities (High / Medium / Low) and NIA v2.1 Critical incidents (IM 8); the mapping note in '
 "sheet 10 is a suggestion for the bank's incident procedure.",
 "NIA v2.1 numbers two statements 'PH 2' and has no PH 1; they are shown as PH 2 (first) and PH 2 (second)."]

NOTICE = 'Built with AI assistance; every requirement and citation checked against the QCB and NCSA source texts. Free to use and adapt; please credit the source.'

OPEN = ['Out-of-band reporting: the add-on applies out-of-band reporting to NCSA for High and Severe risks, in line with the EISRMF reporting section (pp. 20-24) and '
 'the NISRMF (pp. 14, 15, 22). Confirm with NCSA whether the inherent or residual rating applies; the add-on uses the current rating.',
 "Critical National Organisation status: the NIMF and the ECCMF define CNOs (the NIMF: 'organisations that offer critical services in the State of Qatar') but "
 'publish no list, and the EISRMF states that this classification is determined centrally through a defined process overseen by NCSA. Each bank should confirm '
 "its status with NCSA or QCB. If a bank is a CNO, its ECCMF compliance 'will be monitored by sector regulators' (ECCMF).",
 "The QCB Incident Reporting Guideline defines the Sector-Specific Security Regulation as 'QCB Information Security regulations that are applicable to "
 "Entities from a specific subsector within the financial sector in Qatar'. Which document is the Sector-Specific Security Regulation for banks (AI Guideline "
 '17.1, 24.1.1) should be confirmed with QCB.',
 'The QCB Incident Reporting Guideline is understood to have been issued in 2024, but the copy reviewed shows no date; confirm the exact date and circular '
 'number with QCB.',
 'Critical incident deadline for NCSA: the Technology Risks circular (8.2.10) requires critical incidents to be reported to QCB and the relevant governmental '
 'authorities within 1 hour of identification; NIA v2.1 IM 8 sets two hours for NCSA. Neither text says whether NCSA is one of those authorities. Suggested '
 'option until confirmed: report to NCSA within 1 hour. Confirm with QCB and NCSA.']

