SEVERITY_NOTE = ["Suggestion (no official mapping is published): in the bank's incident procedure, assess every QCB High cyber or technology incident as a possible NIA "
 'Critical incident (IM 8) for the NCSA report (2 hours under IM 8; 1 hour suggested until confirmed whether Technology Risks circular 8.2.10 also applies to '
 "NCSA), and record the bank's own severity, the QCB priority and the NCSA decision for each incident. The NCSA category (Red, Orange, Yellow or White) is "
 "assigned by NCSA and is independent of the bank's internal classification (NIMF 4.1), so the bank records it rather than mapping its own scale to it.",
 'An incident is also a risk input (sheet 7): if it shows a High or Severe risk on the national band, the out-of-band risk report to NCSA applies as well. '
 'Under the QCB Incident Reporting Guideline (6.3), an incident reported to NCSA or any other authority must also be reported to QCB.']

