def _ids(s): return [x.strip() for x in s.replace(";", ",").split(",") if x.strip() and x.strip() != "-"]


def agg5a(c, i, a):
    cv, iv, av = int(c[1]), int(i[1]), int(a[1]); mx = max(cv, iv, av)
    lvl = "Not rated" if mx == 0 else ("High" if (cv >= 3 or iv == 3 or av == 3) else ("Medium" if mx == 2 else "Low"))
    add = "two or more additional controls per applicable domain, by risk assessment" if mx >= 3 else ("one or more additional controls per applicable domain, by risk assessment" if mx == 2 else "no additional controls beyond baseline")
    return lvl, add


def ctrl_must(c): return len([x for x in _ids(c["qai"]) + _ids(c["qcd"]) if x in _MUST])


def nia_compact(pairs):
    by = {}
    for d, n in pairs: by.setdefault(d, []).append(n)
    parts = []
    for d, ns in by.items():
        ns = sorted(set(ns)); runs = []; s = p = ns[0]
        for n in ns[1:] + [None]:
            if n is not None and n == p + 1: p = n; continue
            runs.append(f"{s}" if s == p else f"{s}-{p}");
            if n is not None: s = p = n
        parts.append(f"{d} " + ", ".join(runs))
    return "; ".join(parts) if parts else "-"


def nia_expand(ref):
    out = []
    for tok in [t.strip() for t in ref.split(";") if t.strip() and t.strip() != "-"]:
        m = re.fullmatch(r"([A-Z]{2}) (\d+)(?:-(\d+))?", tok)
        a, b = int(m.group(2)), int(m.group(3) or m.group(2))
        out += [(m.group(1), n) for n in range(a, b + 1)]
    return out


def scen_must(s): return "Yes" if any(x in _MUST for x in _ids(s[8])) else "No"


def worked(w):
    sid, aid, cur, tol, res, kris, inc = w
    s = next(x for x in SCEN if x[0] == sid); e = next(x for x in EX5A if x[0] == aid)
    lvl, add = agg5a(e[3], e[4], e[5])
    ctr = [x.strip() for x in s[7].split(",")]
    base = nia_compact(sorted({p for c in ctr for p in nia_expand(CTRL[c]["nia"]) if NIA_IDX[p]["base"]}))
    qrows = "; ".join(f"{x.strip()} ({QCB_ROW[x.strip()]['clauses']})" for x in s[8].split(",") if x.strip() != "-")
    th = next(t for t in THREATS if t[0] == s[2]); vu = next(v for v in VULNS if v[0] == s[3]); at = next(a for a in ASSETS if a[0] == s[1])
    area = AREAS[s[6]]; esc = BANDS.index(cur) > BANDS.index(tol)
    kn = {k[0]: k[2] for k in KRIS}
    rows = [
     ("AI system (5A)", f"{aid} {e[1]} ({e[2]}): rated {e[3]}, {e[4]}, {e[5]}; aggregate level {lvl}. NIA v2.1: all baseline (*) statements apply, plus {add} (2.3). {EX_NOTE[sid]}"),
     ("Scenario (4)", f"{sid} (asset type {s[1]} {at[1]}): {s[4]} Threat {th[0]} {th[1]}; vulnerability {vu[0]} {vu[1]}. Main consequence area: {area}."),
     ("Rating (example)", f"The bank rates the risk on its own scale; the mapping in 9B gives the national band {cur}. " + ("High and Severe risks are reported to NCSA out of band: notify immediately, detailed report within 48 hours (EISRMF)." if cur in ("High", "Severe") else "No out-of-band report to NCSA is needed for this band.")),
     ("Approval and appetite (8A)", f"EISRMF meaning of {cur}: {EIS_BAND[cur]} Approver: the role the bank set for {cur} in 8A, in addition to the risk owner. If the bank set {tol} as the highest acceptable band for {area}, sheet 4 shows " + ('\"Above appetite\" and the risk is escalated to the decision level the bank set in 8A (section C).' if esc else '\"Within appetite\".')),
     ("Treatment (5)", f"Mitigate with " + ", ".join(f"{c} {CTRL[c]['name']}" for c in ctr) + f". QCB rows supported: {qrows}. NIA baseline (*) statements supported: {base}."),
     ("Residual risk, acceptance and monitoring (8B, 6)", f"Target residual band {res} (example). The risk owner approves the treatment plan and accepts the residual risk (ISO/IEC 27001 6.1.3); record it in 8B with the risk owner, the approver set for {res} and the review date from the period set in 8A. Sheet 4 tracks the treatment target date; overdue High or Severe treatments feed K13. Indicators (6): " + "; ".join(f"{k} {kn[k]}" for k in kris) + "." + (" Row RA-01 in 8B is this example." if sid == ACC_EXAMPLE[1] else "")),
     ("If it happens (10)", inc)]
    return s, e, rows
